"""Generate the integration layer from recorded, raw-derived stage summaries."""
from pathlib import Path
import json
import sys
from derive import derive,CASE,A1REL


def md(headers,rows):
    return '| '+' | '.join(headers)+' |\n|'+'|'.join(['---']*len(headers))+'|\n'+''.join('| '+' | '.join(map(str,r))+' |\n' for r in rows)


def content(case=CASE):
    data=derive(case);a1=data['A1'];summary=a1['summary'];runtime=a1['runtime'];p1=data['P1']['summary']
    table=md(['Model','API_V1 verified /16','API_V2 verified /16','Both success','Loss','Gain','Both fail'],[
        [m,*[next(r['verified_success'] for r in summary['success_table'] if r['method']==m and r['api_version']==api) for api in ['API_V1','API_V2']],
         *[next(r[k] for r in summary['paired_regression'] if r['method']==m) for k in ['both_success','loss','gain','both_fail']]] for m in ['BF16','RTN','D16']])
    oldtable=md(['Model','I0 original /8','I1 order /8','I2 lowerCamel /8','I3 opaque /8'],[[m,*[next(r['success'] for r in p1['success_table'] if r['method']==m and r['interface_id']==api) for api in ['I0_ORIGINAL','I1_ORDER_ONLY','I2_STYLE_RENAME','I3_OPAQUE_RENAME']]] for m in ['BF16','RTN','D16']])
    mapping=md(['Semantic ID','API_V1','API_V2'],[['order.read','read_order','readOrder'],['amount.multiply','multiply_amount','multiplyAmount'],['order.write','write_order_total','writeOrderTotal'],['order.validate','validate_order','validateOrder']])
    aux=summary['auxiliary'];auxtext=f"{100*aux['D16_API_change_minus_BF16_API_change']:+.2f} pp; 95% exploratory CI [{100*aux['exploratory_template_bootstrap_CI95'][0]:+.2f}, {100*aux['exploratory_template_bootstrap_CI95'][1]:+.2f}] pp"
    runtime_text=f"{runtime['total_worker_wall_seconds']:.3f}s; {runtime['primary_model_requests']} model requests; {runtime['primary_tool_attempts']} attempted / {sum(r['executed_tool_calls'] for r in __import__('order_regression.common',fromlist=['rows']).rows(case/A1REL/'results/a1_r1/episodes.jsonl'))} executed tools; {runtime['primary_generated_tokens']} generated tokens. Smoke: {runtime['smoke_model_requests']} requests / {runtime['smoke_tool_attempts']} tools / {runtime['smoke_generated_tokens']} tokens. Peak allocated {runtime['max_peak_allocated_bytes']/2**30:.3f} GiB; reserved {runtime['max_peak_reserved_bytes']/2**30:.3f} GiB."
    files={}
    for lang in ['ko','en']:
        ko=lang=='ko';txt=lambda k,e:k if ko else e;suffix='.ko' if ko else ''
        title='Case015 — '+txt('같은 도구, 다른 이름','Same Tools, Different Interfaces')
        intro=txt('API 이름 변경 전후의 조회·계산·기록 수정·검증을 자동 비교하는 도구를 구현했습니다. 생성 전에 받은 결과와 실제 JSON 상태를 따로 기록하고, 저장 응답을 새 fixture에서 재실행해 성공 판정을 검산합니다.','Built tools that compare lookup, calculation, record updates and validation across an API rename. They record results received before generation separately from actual JSON state, then replay saved responses into fresh fixtures to audit success.')
        observed=txt('새 A1 96개 실측에서 BF16은 15/16→16/16, RTN은 16/16→16/16, D16은 12/16→12/16이었습니다. BF16 회복 1건, 이름 변경에 따른 손실 0건입니다. D16의 동일 4개 fixture 실패는 두 API에 남았습니다.','Across 96 new measured A1 episodes, BF16 changed15/16→16/16, RTN 16/16→16/16 and D16 12/16→12/16. There was one BF16 recovery and no rename-related losses. D16 failed on the same four fixtures on both APIs.')
        readme=f"# {title}\n\n{intro}\n\n{observed}\n\n{table}\n"+txt('\n한 합성 주문 업무 · 4개 영어 지시문 표현 · 16개 fixture · Qwen3-4B-Instruct-2507. 기존 P1의 96개와 분모를 합치지 않습니다. 품질은 저장 INT4를 dense BF16으로 복원해 측정했습니다.\n','\nOne synthetic order workflow · four English instruction templates · 16 fixtures · Qwen3-4B-Instruct-2507. The 96 original P1 episodes keep a separate denominator. Quality uses dense BF16 reload of saved INT4 artifacts.\n')
        readme+=f"\n[Pages](https://munsik-kim.github.io/inference-lab/{lang}/case015.html#overview) · [REPORT](REPORT{suffix}.md) · [CPU / GPU](REPRODUCE{suffix}.md) · [Stage map](STAGE_MAP.md) · [A1 runner]({A1REL}/src/order_regression/runner.py) · [Tests]({A1REL}/tests/test_order_contracts.py)\n"
        readme+=txt('\n## 세 가지 구현\n\n1. 정확한 이름↔의미 mapping과 두 API의 실제 동작 동등성 검사.\n2. 조회 결과 수신→계산 결과 수신→저장·검증→최종 답의 관측 계약.\n3. 원 응답·실제 상태 재실행과 모델별 손실·회복 회귀표.\n','\n## Three implemented functions\n\n1. Exact name↔semantic mapping and executed API equivalence.\n2. A receipt contract from lookup to multiplication, write/validation and final answer.\n3. Raw-response/state replay with per-model loss/gain regression tables.\n')
        readme+=txt('\n## 기존 P1도 보존했습니다\n\n기존 8개 DEV task×3방법×4인터페이스의 signed interaction은 +8.33pp, 95% 구간 [-8.33,+25.00]pp로 불확정입니다. [원 보고서](publication/originals/p1_review/REPORT.ko.md)와 [원형 복원 mapping](publication/provenance/p1_original_map.json)을 유지합니다.\n','\n## The original P1 is preserved\n\nFor eight previously observed DEV tasks × 3 methods×4 interfaces, the signed interaction was+8.33pp with 95% CI [-8.33,+25.00]pp, inconclusive. See the [original report](publication/originals/p1_review/REPORT.md) and [restoration map](publication/provenance/p1_original_map.json).\n')
        files['README'+suffix+'.md']=readme
        headings=txt(['배경','질문과 가설','원리와 실행 계약','방법','실험','결과','실패와 회복 분석','결론','재현과 출처'],['Background','Questions and hypotheses','Principles and execution contract','Method','Experiment','Results','Failure and recovery analysis','Conclusion','Reproduction and sources'])
        report=f"# {title}\n\n## "+txt('요약','Abstract')+f"\n\n{intro}\n\n{observed}\n\n"+' · '.join(f'[{i+1}. {h}](#section-{i+1})' for i,h in enumerate(headings))+'\n'
        def sec(i,body):return f'\n<a id="section-{i}"></a>\n## {i}. {headings[i-1]}\n\n'+body+'\n'
        report+=sec(1,txt('이름 문자열이 바뀌어도 같은 도구라면 업무를 끝낼 수 있을까? 기존 P1은 long-context DEV의 이름·순서를 바꾸어 실패와 회복을 관측했습니다. A1은 그 결과를 본 뒤 설계한 새 응용시험이며 실제 회사나 결제 시스템에 연결하지 않았습니다.','Can an agent finish the same workflow when tool names change? P1 varied names/order on long-context DEV tasks and observed losses and gains. A1 is a new application designed after P1, without connecting to a business or payment system.'))
        report+=sec(2,txt('주 질문은 모델별 API_V1→API_V2의 유지 성공·손실·회복·양쪽 실패입니다. API_V2가 더 좋아야 한다는 가설은 없습니다. D16 변화−BF16 변화는 보조 비교이며 한 업무·4개 표현의 탐색 범위입니다.','The primary display is each model’s paired API_V1→API_V2 both-success/loss/gain/both-fail table, without a directional superiority hypothesis. D16 change minus BF16 change is secondary and exploratory over one workflow and four templates.'))
        report+=sec(3,mapping+'\n'+txt('이름만 lowerCamelCase로 바꾸고 설명·인자·순서를 유지했습니다. registry는 전단사이며 옛 이름·오탈자를 거절합니다. 생성 응답 안의 모든 호출은 동일한 immutable available_result_event_ids를 공유합니다. 곱셈은 read 결과 수신 후, write는 올바른 곱셈 결과 수신 후 생성해야 합니다. write와 validate는 같은 응답에서 순서대로 실행할 수 있습니다. 최종 true는 현재 state version에 대응하는 validation을 이미 받은 경우만 허용합니다.','Only names change to lowerCamelCase; descriptions, arguments and order stay fixed. The bijective registry rejects old names and typos. Every call within a response shares immutable available_result_event_ids. Multiplication must be generated after receipt of the read result, writing after receipt of the correct product. Write and validate may execute in that order within one response. Final true requires receipt of validation matching the current state version.'))
        report+=sec(4,txt('주 endpoint VERIFIED_WORKFLOW_SUCCESS는 실행된 read→multiply→write→validate와 관측 계약, 실제 정수 total, 전 과정의 타 주문/불변 필드 보존, 현재 검증 수신, 정확한 세 필드 JSON을 모두 요구합니다. bool을 int와 동치로 세지 않습니다. schema가 맞는 잘못된 정수는 실제 계산·저장되며 oracle이 고치지 않습니다. STATE_ONLY_SUCCESS와 FINAL_ANSWER_CORRECT는 별도입니다.','VERIFIED_WORKFLOW_SUCCESS requires the executed read→multiply→write→validate chain and receipt order, actual integer total, other-order/immutable-field preservation throughout, received current validation and an exact three-field final JSON. Bool and int are distinct. Wrong schema-valid integers execute/store as given; the oracle does not repair them. STATE_ONLY_SUCCESS and FINAL_ANSWER_CORRECT remain separate.'))
        report+=sec(5,txt('seed 6101621로 4 template×4fixture=16 scenario와 별도 smoke1을 만들고, ID와 금액을 독립 생성했습니다. 수량2..40, 단가100..20,000의 정수이며 초기 total은 null 또는 -1입니다. 초기 요청은 수량/단가를 노출하지 않습니다. 토큰 길이는 506..518로 기존 P1의4K/8K와 다릅니다. 16×2API×3방법=96 본 episode, BF16 두 API smoke2를 별도 실행했습니다. 순서 seed 6101622와 BF16→D16→RTN을 등록했습니다.','Seed 6101621 generated four templates × four fixtures = 16 scenarios and one distinct smoke fixture; IDs and amounts are independent. Quantities 2..40 and unit prices 100..20,000 are integers; initial totals are null or -1. Requests hide quantity/price. Initial lengths 506..518 tokens differ from P1’s 4K/8K contexts. The matrix is 16 × 2 APIs × 3 methods = 96 primary episodes, plus two separate BF16 smoke episodes. Seed 6101622 fixes within-method order; load order is BF16→D16→RTN.')+'\n\n'+txt('같은 revision cdbee75f17c01a7cc42f958dc650907174af0554, greedy 192token, enable_thinking=False, 최대8모델 요청·6도구 시도·900초, context 24576, BF16/SDPA, logits_to_keep=1, within-request KV ON/turn cache OFF입니다. ENUM·추가 feedback·alias는 OFF. 252개씩의 원 RTN/D16 저장본을 읽었고 D16 beta_inverse/W_pre 경로를 유지했습니다.','Revision cdbee75f17c01a7cc42f958dc650907174af0554, greedy 192-token generation, enable_thinking=False, at most 8 requests/6 tool attempts/900 seconds, context 24576, BF16/SDPA, logits_to_keep=1, within-request KV ON/turn cache OFF. ENUM, enhanced feedback and aliases are OFF. Original 252-projection RTN/D16 artifacts are read-only; D16 beta_inverse/W_pre transport is preserved.'))
        report+=sec(6,'### A1\n\n'+table+'\n'+txt('부가 D16−BF16 API 변화: ','Secondary D16−BF16 API change: ')+auxtext+'\n\n'+txt('구간은 seed 6101623의 10,000회 template 묶음 재표집입니다. 4개 template와 고정 이름 변경 하나에 조건화한 탐색 구간이며 API 모집단의 배포 승인·동등성 구간이 아닙니다.','Intervals use 10,000 template-group resamples, seed 6101623. They are exploratory and conditional on four templates and one fixed rename, not API-population deployment or equivalence guarantees.')+'\n\n### P1\n\n'+oldtable+'\n'+txt('원 P1 주 interaction +8.33pp, 95% CI [-8.33,+25.00]pp; 손실과 회복을 별도 보존했습니다. 두 단계의 96개를192개의 같은 점수로 합산하지 않습니다.','Original P1 primary interaction +8.33pp,95% CI [-8.33,+25.00]pp; losses and gains are retained separately. The two stages are not pooled into a 192-episode common success rate.')+'\n\n### '+txt('비용','Cost')+'\n\n'+runtime_text+'\n\n'+txt('Worker wall은 모델 hash·load·decode·smoke·실패·I/O를 포함합니다. Torch allocator peak와 Windows 배경 사용을 구분한 장치 free/total 표본을 응답별로 남겼습니다. serving 속도나 native INT4 가속 측정이 아닙니다.','Worker wall includes model hashing/loading, artifact decoding, smoke, failures and I/O. Each response retains device free/total samples separately from Torch allocator peaks and Windows background use. This is not serving latency or native INT4 acceleration.'))
        report+=sec(7,txt('BF16 / A1-06: V1은191444를 올바르게 저장했지만 validate_order의 주문 ID를 ...3657 대신 ...3659로 생성했습니다. 오류 결과를 받고 validated:false로 끝났습니다. V2는 원 대상 ID로 검증하고 성공했습니다. D16은 A1-00/06/08/14에서 두 API 모두 write 호출 JSON을 완성하지 못해 저장 전에 끝났습니다. 미등록 이름과 관측 순서 위반은0건입니다. API 변화가 D16의 이 parse 실패를 회복시키지 않았습니다.','BF16 / A1-06: V1 saved 191444 correctly but generated validation order ID...3659 instead of...3657, received an error and ended with validated:false. V2 validated the target ID and succeeded. D16 failed to complete write-call JSON for A1-00/06/08/14 on both APIs and stopped before saving. Unknown names and receipt-order violations were zero. The rename did not repair these D16 parse failures.')+'\n\n'+txt('기록 결함을 사후 주석으로 분리했습니다. malformed-only 응답에서 조기 종료한8건의 원 terminal_reason은 초기값 BUDGET_EXHAUSTED로 남았으나 실제 모델/도구 예산은 소진하지 않았습니다. 별도 주석은 PARSE_ERROR로 설명합니다. 잘못된 주문 ID1건은 원 summary의 ARGUMENT_VALUE_WRONG에 빠졌지만 원 tool event에 UNKNOWN_ORDER/BAD_ARGUMENTS로 남아 있어 주석에서 값 오류로 집계합니다. 원 응답·코드 동결·성공 판정은 그대로이며 독립 endpoint 재계산의 영향은0건입니다. 조기 parse-only 종료 후의 recovery는 관측하지 않았습니다.','Post-hoc annotations separate diagnostic record defects. Eight malformed-only early stops retained the initial BUDGET_EXHAUSTED terminal label despite neither request nor tool budgets being exhausted; separate annotations explain PARSE_ERROR. The wrong-order-ID case was omitted from raw summary ARGUMENT_VALUE_WRONG but retained as UNKNOWN_ORDER/BAD_ARGUMENTS in its tool event, and is counted in the annotation. Original responses, frozen source and success verdicts remain unchanged; independent endpoint recomputation changes zero outcomes. Recovery after parse-only early stops was not observed.')+'\n\n'+txt('P1은 실행 직전 같은 fixture와 생성 전 같은 관측을 별도로 고정하지 않았습니다. 새 표시 계층은 그 둘을 구분하며 A1 계약으로 옛 점수를 고치지 않습니다.','P1 did not separately register equal pre-execution fixtures and equal pre-generation observations. The new display distinguishes them without rescoring old records under the A1 contract.'))
        report+=sec(8,txt('한 주문 워크플로에서 이름 변경 회귀를 추적·재실행하는 도구를 완성했습니다. API_V2에서 손실은 없고 BF16 회복1건이 있었지만, D16의4개 fixture 실패는 남았습니다. 기존 P1의 인터페이스 민감도와 같은 현상으로 단정할 수 없습니다. 다음 연구는 P2 복구 진단을 별도 승인·등록하고 동일 관측을 주는 대조를 포함하는 것입니다.','The tool now traces and replays rename regressions in one order workflow. V2 caused no losses and one BF16 recovery, while four D16 fixture failures remained. These are not automatically the same mechanism as P1 interface sensitivity. A next study would separately authorize/register P2 recovery diagnostics with controls matched on received information.'))
        report+=sec(9,f'[CPU / GPU commands](REPRODUCE{suffix}.md) · [A1 raw]({A1REL}/results/a1_r1/episodes.jsonl) · [Independent audit]({A1REL}/results/a1_r1/independent_audit.json) · [Diagnostic annotation]({A1REL}/results/a1_r1/diagnostic_annotations.json) · [Source freeze]({A1REL}/provenance/source_freeze.json) · [Original P1](publication/originals/p1_review/REPORT{suffix}.md) · [NOTICE](NOTICE.md)\n\n'+txt('27개 원 P1 회귀와18개 새 A1 고유 검사를 구분합니다. CPU 감사는 원 응답96개·실제 호출368개·요청463개의 대응과 상태/관측 판정을 재구성했으며 GPU 추론 자체를 재현하지 않습니다. Codex/ChatGPT 보조와 별도 CPU 계산 검토이며 사람의 독립 심사나 저자 승인이 아닙니다.','The 27 frozen P1 regression methods and 18 new A1 unique tests are counted separately. CPU audit reconstructs 96 raw episodes, 368 executed calls and 463 requests with state/receipt verdicts; it does not reproduce GPU inference. Codex/ChatGPT assistance and separate CPU calculation review are not human peer review or author endorsement.'))
        files['REPORT'+suffix+'.md']=report
    return files


if __name__=='__main__':
    for name,value in content().items():
        # These seven original top-level files were archived byte-for-byte first.
        (CASE/name).write_text(value,encoding='utf-8')
